document.addEventListener('change',event=>{const id=event.target.id;if(!['u-report-date-mode','u-report-date','u-report-sort'].includes(id))return;if(id==='u-report-date-mode'){unifiedReportDateMode=event.target.value;if(unifiedReportDateMode==='single'){state.from=state.from||today();state.to=state.from;}}if(id==='u-report-date')state.from=state.to=event.target.value||today();if(id==='u-report-sort')unifiedReportSort=event.target.value;state.page=0;render();});
document.addEventListener('change',event=>{if(event.target.id==='u-status'||event.target.id==='u-min'){unifiedStatus=$('#u-status').value;unifiedMin=$('#u-min').value;state.page=0;render();}});
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target?.dataset.action.startsWith('u-'))return;event.preventDefault();event.stopImmediatePropagation();(async()=>{switch(target.dataset.action){case'u-new':await unifiedNew();break;case'u-open':if(unifiedEditor?.dirty&&!confirm(APG.t('Leave this entry? Unsaved changes will be lost.')))break;if(target.dataset.id)await unifiedOpen(target.dataset.id);break;case'u-back':unifiedEditor=null;await render();break;case'u-refresh-balances':uCapture();unifiedEditor.prior=null;await unifiedAfterRender();break;case'u-report-status':unifiedReportStatus=target.dataset.value;state.page=0;await render();break;case'u-report-clear':state.from=state.to=today();state.search='';state.page=0;unifiedReportDateMode='single';unifiedReportSort='newest';await render();break;case'u-tab':if(target.dataset.value==='all'){state.from=state.to='';unifiedStatus='';unifiedMin='';}if(target.dataset.value==='reports'&&unifiedTab!=='reports'){state.from=state.to=today();unifiedReportDateMode='single';}unifiedTab=target.dataset.value;unifiedEditor=null;state.page=0;state.search='';await render();break;case'u-fetch':clearTimeout(uLookupTimer);await uFetch();break;case'u-add':await uAdd(unifiedEditor.matches?.get(Number(target.dataset.id)));break;case'u-remove':uCapture();unifiedEditor.dirty=true;unifiedEditor.rows=unifiedEditor.rows.filter(row=>row.key!==Number(target.dataset.id));unifiedEditor.prior=null;await render();break;case'u-review':await unifiedOpen(target.dataset.delivery,target.dataset.id);break;case'u-full':uCapture();if(!unifiedEditor.prior){toast('Wait for customer balances to load before saving.');break;}unifiedEditor.dirty=true;{const paidCustomers=new Set(),previous=uCustomerPreview().previous;for(const row of unifiedEditor.rows){const a=uAmounts(row),v=unifiedEditor.values,key=row.key;unifiedEditor.biltyEntries??=new Set();unifiedEditor.biltyEntries.add(String(key));v['u_bilty_'+key]=amount(Math.max(0,a.biltyDue-Number(row.bilty_received||0))+(paidCustomers.has(row.account_id)?0:previous.get(row.account_id)||0));paidCustomers.add(row.account_id);const leftLoading=Math.max(0,a.loading-Number(row.loading_received||0)),leftSuzuki=Math.max(0,a.suzuki-Number(row.suzuki_received||0)),leftCombined=Math.max(0,a.serviceDue-Number(row.service_received||0));const loadingCash=unifiedEditor.doc?.header.legacy_services?Math.min(leftLoading,leftCombined):leftLoading,suzukiCash=unifiedEditor.doc?.header.legacy_services?Math.max(0,leftCombined-loadingCash):leftSuzuki;unifiedEditor.serviceEntries??=new Set();unifiedEditor.serviceEntries.add(String(key));v['u_service_cash_'+key]=amount(loadingCash+suzukiCash);for(const field of ['bilty','service_cash'])v['u_date_'+field+'_'+key]=Number(v['u_'+field+'_'+key])>0?today():'';}}await render();break;case'u-print':if(unifiedEditor?.dirty){toast('Save changes before printing.');break;}{const delivery=await api('delivery',null,{id:unifiedEditor.doc.header.id});recordPrintContext={kind:'delivery',variant:printFormat()==='a4'?'sheet':'receipt',data:structuredClone(delivery)};openThermalPreview('dialog');}break;}})().catch(error=>toast(error.message));});
function uAlignRows(){
 const grids=document.querySelector('.u-two-grids');if(!grids)return;
 for(const section of grids.querySelectorAll('section')){
  const labels=[...section.querySelectorAll('thead th')].map(cell=>cell.textContent.trim());
  for(const row of section.querySelectorAll('tbody tr'))[...row.cells].forEach((cell,index)=>cell.dataset.label=APG.t(labels[index]||'Remove'));
 }
 const stacked=matchMedia('(max-width:1100px)').matches;
 const left=grids.querySelectorAll('[data-u-bilty-row]');
 for(const row of left){const other=grids.querySelector('[data-u-service-row="'+row.dataset.uBiltyRow+'"]');if(!other)continue;row.style.height='';other.style.height='';if(!stacked){const height=Math.max(96,row.getBoundingClientRect().height,other.getBoundingClientRect().height);row.style.height=height+'px';other.style.height=height+'px';}}
 const a=grids.querySelector('.u-bilty-grid thead tr'),b=grids.querySelector('.u-services-grid thead tr');if(a&&b){a.style.height='';b.style.height='';if(!stacked){const h=Math.max(a.getBoundingClientRect().height,b.getBoundingClientRect().height);a.style.height=b.style.height=h+'px';}}
}
window.addEventListener('resize',()=>requestAnimationFrame(uAlignRows));window.addEventListener('apg-language-change',()=>requestAnimationFrame(uAlignRows));
